Greetings!

I am trying to establish a connection between STM32F439IIH6 (Slave) and a customize board (Master) through SPI DMA application. The customize board has its own built-in driver with SPI application. The communication between STM32F4 and customize board eventually broke down after few thousands of cycles. Through some investigation, I found out that the SPI\_WaitOnFlagUntilTimeout() hangs inside SPI\_DMATransmitReceiveCplt(). It sutcks inside the else statement of SPI\_WaitOnFlagUntilTimeout(). The clock used in customize board (Master) is **80Mhz** with **clock division 4**

```

/**

* @brief This function handles SPI Communication Timeout.

* @PAram hspi: pointer to a SPI_HandleTypeDef structure that contains

* the configuration information for SPI module.

* @retval HAL status

*/

static HAL_StatusTypeDef SPI_WaitOnFlagUntilTimeout(SPI_HandleTypeDef *hspi, uint32_t Flag, FlagStatus Status, uint32_t Timeout)

{

uint32_t tickstart = 0;

/* Get tick */

tickstart = HAL_GetTick();

/* Wait until flag is set */

if(Status == RESET)

{

while(__HAL_SPI_GET_FLAG(hspi, Flag) == RESET)

{

if(Timeout != HAL_MAX_DELAY)

{

if((Timeout == 0)||((HAL_GetTick() - tickstart ) > Timeout))

{

/* Disable the SPI and reset the CRC: the CRC value should be cleared

on both master and slave sides in order to resynchronize the master

and slave for their respective CRC calculation */

/* Disable TXE, RXNE and ERR interrupts for the interrupt process */

__HAL_SPI_DISABLE_IT(hspi, (SPI_IT_TXE | SPI_IT_RXNE | SPI_IT_ERR));

/* Disable SPI peripheral */

__HAL_SPI_DISABLE(hspi);

/* Reset CRC Calculation */

if(hspi->Init.CRCCalculation == SPI_CRCCALCULATION_ENABLED)

{

__HAL_SPI_RESET_CRC(hspi);

}

hspi->State= HAL_SPI_STATE_READY;

/* Process Unlocked */

__HAL_UNLOCK(hspi);

return HAL_TIMEOUT;

}

}

}

}

else

{

while(__HAL_SPI_GET_FLAG(hspi, Flag) != RESET)

{

if(Timeout != HAL_MAX_DELAY)

{

if((Timeout == 0)||((HAL_GetTick() - tickstart ) > Timeout))

{

/* Disable the SPI and reset the CRC: the CRC value should be cleared

on both master and slave sides in order to resynchronize the master

and slave for their respective CRC calculation */

/* Disable TXE, RXNE and ERR interrupts for the interrupt process */

__HAL_SPI_DISABLE_IT(hspi, (SPI_IT_TXE | SPI_IT_RXNE | SPI_IT_ERR));

/* Disable SPI peripheral */

__HAL_SPI_DISABLE(hspi);

/* Reset CRC Calculation */

if(hspi->Init.CRCCalculation == SPI_CRCCALCULATION_ENABLED)

{

__HAL_SPI_RESET_CRC(hspi);

}

hspi->State= HAL_SPI_STATE_READY;

/* Process Unlocked */

__HAL_UNLOCK(hspi);

return HAL_TIMEOUT;

}

}

}

}

return HAL_OK;

}

```

I tried send a dummy message to the slave and it 'reset' the flag and breaks the loop. The message received from previous cycle still remain intact. Is it possible that the timing mismatch between master and slave the main cause?

Below is simplified code segment from STM32F4 (Slave)

STM32F439IIH6(Slave)

```

#define BUFFER_SIZE 37 //37 bytes messages

void Main()

{

SPI_DMA_Init(); //Initialize SPI_DMA application

//Start receiving and transmiting message

While(1)

{

Toggle_GPIO_Pin(); //an extra gpio pin to notify master that slave ready for next cycle

While(!HAL_READ_GPIO(SPI2_NSS_PORT, SPI2_NSS_PIN, GPIO_PIN_RESET) //waiting NSS pin drop)

if(HAL_SPI_TransmitReceive_DMA(&SpiHandle, recv_packet, trns_buffer, BUFFER_SIZE) != HAL_OK)

{

}

Toggle_GPIO_Pin(); //block the next cycle

while(HAL_SPI_GetState(SpiHandle) != HAL_SPI_STATE_READY)

{

}

restart_SPI_DMA(); //Deinitalize and reinitalize SPI_DMA for next cycle, excluding the extra GPIO.

}

}

```

Here's is the summarize of the configuration of SPI\_DMA that I use.

